<div class="flex flex-col lg:flex-row justify-between gap-3 mb-5"><form method="GET" data-qf-auto-filter class="card p-4 grid grid-cols-1 sm:grid-cols-3 gap-3 flex-1 items-center"><input class="input" name="search" value="<?php echo e(request('search')); ?>" placeholder="Search staff..." autocomplete="off"><select class="input" name="office_id"><option value="">All offices</option><?php $__currentLoopData = $offices; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $office): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($office->id); ?>" <?php if(request('office_id')==$office->id): echo 'selected'; endif; ?>><?php echo e($office->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select class="input" name="status"><option value="">All statuses</option><option value="active" <?php if(request('status')==='active'): echo 'selected'; endif; ?>>Active</option><option value="inactive" <?php if(request('status')==='inactive'): echo 'selected'; endif; ?>>Blocked</option></select><span class="qf-auto-filter-status" role="status" aria-live="polite"><span class="qf-auto-filter-spinner" aria-hidden="true"></span><span data-qf-filter-status>Updating...</span></span></form><a href="<?php echo e(route('admin.staff.create')); ?>" class="btn-primary self-start">+ Add Staff</a></div>
<div class="card"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Office</th><th>Office Status</th><th>Assigned Courses</th><th>Phone</th><th>Status</th><th></th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $staff; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $member): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td class="font-semibold"><?php echo e($member->name); ?></td><td><?php echo e($member->email); ?></td><td><?php echo e($member->office->name ?? 'Unassigned'); ?></td><td><?php if($member->office): ?><?php $o = $member->office; ?><div class="flex items-center gap-2"><span class="badge <?php echo e($o->isOnline() ? 'badge-online' : 'badge-offline'); ?>"><?php echo e(strtoupper($o->status ?: \App\Models\Office::STATUS_OFFLINE)); ?></span></div><?php else: ?><span class="text-slate-400">—</span><?php endif; ?></td><td><?php $__empty_2 = true; $__currentLoopData = $member->assignedCourses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $course): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_2 = false; ?><span class="badge bg-slate-100 text-slate-600"><?php echo e($course->code); ?></span><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_2): ?><span class="text-slate-400">—</span><?php endif; ?></td><td><?php echo e($member->phone ?? '—'); ?></td><td><span class="badge <?php echo e($member->is_active ? 'badge-served' : 'badge-cancelled'); ?>"><?php echo e($member->is_active ? 'Active':'Blocked'); ?></span></td><td><div class="flex justify-end gap-2"><a class="btn-secondary text-xs" href="<?php echo e(route('admin.staff.edit',$member)); ?>">Edit</a><?php if($member->is_active): ?><form method="POST" action="<?php echo e(route('admin.staff.block',$member)); ?>" onsubmit="return confirm('Block <?php echo e($member->name); ?>? They will no longer be able to sign in.')"><?php echo csrf_field(); ?><button class="btn-warning text-xs">Block</button></form><?php else: ?><form method="POST" action="<?php echo e(route('admin.staff.unblock',$member)); ?>" onsubmit="return confirm('Unblock <?php echo e($member->name); ?>? They will be able to sign in again.')"><?php echo csrf_field(); ?><button class="btn-success text-xs">Unblock</button></form><?php endif; ?><form method="POST" action="<?php echo e(route('admin.staff.destroy',$member)); ?>" onsubmit="return confirm('Delete this staff account?')"><?php echo csrf_field(); ?> <?php echo method_field('DELETE'); ?><button class="btn-danger text-xs">Delete</button></form></div></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="8" class="text-center text-slate-500 py-10">No staff accounts found.</td></tr><?php endif; ?></tbody></table></div><div class="p-4"><?php echo e($staff->links()); ?></div></div>
